#!/usr/bin/env bash
# Вход в сессию: канон печатается сам. Правило, которое надо вспоминать,
# не работает — работает то, которое печатается.
set -u
HOME_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPO="$(cd "$HOME_DIR/../.." && pwd)"

echo "=============================================================="
echo " Librarer — дом исполнителя в refedoc. Роль: ПОГРАНИЧНИК."
echo " refedoc — ПУБЛИЧНАЯ зона. Источники — приватная."
echo "--------------------------------------------------------------"
echo " 1. Стенограммы переписки сюда НЕ кладутся: ни chatlog/, ни"
echo "    sessions/, ни context-export/, ни *.jsonl, ни пересказ."
echo "    Отчёт по чатлогу — в приватный репозиторий-источник."
echo " 2. Секреты и ключи — тем более. Опубликованное не"
echo "    разопубликовать: удаление оставляет их в истории."
echo " 3. Производное (INVENTORY.md, index.json, указатели) собирается"
echo "    прогоном и руками не правится."
echo " 4. Не плодить ветки: работа в main. Ветка — только если без неё"
echo "    нельзя, и живёт до слияния. Неслитая ветка не работа, а её вид."
echo " 5. ДОПУСТИМОЕ ПУБЛИКУЕТСЯ. Недопустимое не выкладывается никак —"
echo "    ни целиком, ни кусками. Ворота: rights.json + guard.py (блокируют)."
echo " 6. Параллелизм по умолчанию: независимое запускается разом, долгое —"
echo "    в фон. Последовательность без зависимости есть пустое ожидание."
echo "    Ответ автору — сразу, в пределах 1-2 минут; прогон ждёт в фоне."
echo " 7. OCR только для опознания документа. Содержание, формулы, индексы"
echo "    и цитаты — из авторского текстового слоя или из растра глазами."
echo "--------------------------------------------------------------"
echo " Канон целиком : env/Librarer/RULES.md"
echo " Досмотр вручную: python3 env/Librarer/hooks/guard.py staged"
echo " Разбор прав    : python3 tools/rights_classify.py --workspace /home/user --out ."
echo " Поставить крючки: bash env/Librarer/hooks/install.sh"
echo "=============================================================="

# Чужие изменения: репозиторий общий, и соседний дом кладёт сюда своё по
# плану. Появление чужой папки не должно быть неожиданностью — поэтому она
# называется на входе, а не обнаруживается случайно.
if git -C "$REPO" rev-parse --git-dir >/dev/null 2>&1; then
  git -C "$REPO" fetch --quiet origin 2>/dev/null || true
  NEW=$(git -C "$REPO" log --oneline HEAD..origin/main 2>/dev/null | head -5)
  if [ -n "$NEW" ]; then
    echo " ЧУЖИЕ ИЗМЕНЕНИЯ на origin/main (не из этой сессии):"
    echo "$NEW" | sed 's/^/   /'
    echo "   Досмотреть: git diff --name-only HEAD..origin/main | xargs python3 env/Librarer/hooks/guard.py path"
  fi
  echo " Каталоги верхнего уровня: $(ls -1 "$REPO" | grep -v '^\.' | tr '\n' ' ')"
fi

if [ ! -x "$REPO/.git/hooks/pre-commit" ]; then
  echo " ВНИМАНИЕ: git-крючок pre-commit не поставлен — граница держится"
  echo " только на дисциплине. Поставьте: bash env/Librarer/hooks/install.sh"
fi
